/**
 * Equivalence pin for the A1 refactor (2026-11-17): `buildRecommendPrompt`
 * must emit byte-for-byte the prompt that app/api/recommend/route.ts built
 * inline before the move. The golden files were generated by running the
 * pre-refactor template (route.ts @ 8eb631c, extracted verbatim) on
 * PROMPT_FIXTURES, so any edit to the template fails here until the goldens
 * are deliberately regenerated.
 *
 * 2026-11-17 (CKD fluid-neutral): senior-warfarin-ckd.golden.txt was
 * hand-edited — +CKD_FLUID_PROMPT line, −the senior "drink often" phrase,
 * −the water goal / water intake lines (fluid-neutral users).
 * 2026-11-17 (CKD protein cap): hand-edited again — the CKD protein line
 * moved from after the 禁忌 line into the health-context block (after the
 * fluid line) and gained the "cap beats the user's goal" sentence.
 * 2026-11-17 (cap floor): hand-edited — 42g → 41g, because ckdProteinCapG
 * now floors (0.8 × 52 kg = 41.6 → 41) so the cap never exceeds 0.8 g/kg.
 * The other two fixtures (non-CKD) still match the pre-refactor template.
 */
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { buildRecommendPrompt, SYSTEM_PROMPT } from '@/lib/recommend-prompt';
import { buildSafetyReport } from '@/lib/recommend-safety';
import { PROMPT_FIXTURES } from './fixtures/recommend-prompt-cases';

const golden = (name: string): string =>
  readFileSync(path.join(__dirname, 'fixtures', `recommend-prompt-${name}.golden.txt`), 'utf8');

describe('buildRecommendPrompt', () => {
  it.each(Object.keys(PROMPT_FIXTURES))('matches the pre-refactor inline prompt: %s', (name) => {
    const body = PROMPT_FIXTURES[name];
    const safety = buildSafetyReport(body.profile, body.weightKg ?? null);
    expect(buildRecommendPrompt(body, safety.promptInjection)).toBe(golden(name));
  });

  it('starts with the system prompt followed by a blank line', () => {
    const body = PROMPT_FIXTURES['minor-no-weight'];
    expect(buildRecommendPrompt(body, '').startsWith(SYSTEM_PROMPT + '\n\n【ユーザープロフィール】')).toBe(true);
  });

  it('falls back to 特記事項なし when the safety injection is empty', () => {
    const body = PROMPT_FIXTURES['control-unknown-labels'];
    expect(buildRecommendPrompt(body, '')).toContain('【安全制約（必ず遵守）】\n特記事項なし');
  });
});
